WITH recent_web_events AS (SELECT * FROM web_events WHERE (session_id IN (25, 27) AND page = '/cart') OR duration_sec BETWEEN 335 AND 419), event_type_summary AS (SELECT event_type, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range, SUM(CASE WHEN event_type = 'page_view' THEN duration_sec ELSE 0 END) AS page_view_duration_sec FROM recent_web_events GROUP BY event_type) SELECT * FROM event_type_summary
